1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { AnimatePresence, motion } from 'framer-motion';
4	import {
5	  getMinhaEmpresa, getCaixa, abrirCaixa, fecharCaixa, fecharETransferir,
6	  adicionarSaida, toggleStatusRestaurante, getRelatorioFretes,
7	} from '../../services/restauranteService';
8	import { useAuth } from '../../contexts/AuthContext';
9	import Icon from '../../components/AppIcon';
10	import RelatorioPanel from './RelatorioPanel';
11	import SaidaModal from './SaidaModal';
12	import FecharCaixaModal from './FecharCaixaModal';
13	import { supabase } from '../../lib/supabase';
14	import KpiCard from './KpiCard';
15	import AlertasToast from './AlertasToast';
16	import MobileMenu from '../../components/restaurante/MobileMenu';
17	import RestauranteSidebar from '../../components/restaurante/RestauranteSidebar';
18	import { useSolicitacoesMotoboyCount } from '../../hooks/useSolicitacoesMotoboyCount';
19	import { useTipoRestaurante } from '../../hooks/useTipoRestaurante';
20	
21	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
22	
23	const PAGAMENTO_LABEL = { cash: 'Dinheiro', pix: 'PIX', credit_card: 'Cartão crédito', debit_card: 'Cartão débito' };
24	const PAGAMENTO_ICONE = { cash: '💵', pix: '📲', credit_card: '💳', debit_card: '💳' };
25	
26	const LINKS = [
27	  { label: 'Dashboard', path: '/restaurante' },
28	  { label: 'Relatórios', path: '/restaurante/relatorios' },
29	  { label: 'Delivery', path: '/restaurante/delivery' },
30	  { label: 'Cozinha', path: '/restaurante/cozinha' },
31	  { label: 'Produtos', path: '/restaurante/produtos' },
32	  { label: 'Pedidos', path: '/restaurante/pedidos' },
33	  { label: 'Entregas', path: '/restaurante/entregas' },
34	  { label: 'Motoboys', path: '/restaurante/motoboys' },
35	  { label: 'Clientes', path: '/restaurante/clientes' },
36	  { label: 'Financeiro', path: '/restaurante/financeiro' },
37	  { label: 'Caixa', path: '/restaurante/caixa' },
38	  { label: 'Designer', path: '/restaurante/aparencia' },
39	  { label: 'Cardápio Digital', path: '/restaurante/cardapio-digital' },
40	  { label: 'Config', path: '/restaurante/config' },
41	  { label: 'Sessão', path: '/restaurante/sessao' },
42	];
43	
44	const COPA_LINK = [
45	  { label: 'Produção', path: '/restaurante/producao' },
46	  { label: 'Bar', path: '/restaurante/bar' },
47	];
48	
49	const SALAO_LINKS = [
50	  { label: 'Salão', path: '/restaurante/salao' },
51	  { label: 'Garçons', path: '/restaurante/garcons' },
52	  { label: 'Impressoras', path: '/restaurante/impressoras' },
53	];
54	
55	const RestauranteDashboard = () => {
56	  const navigate = useNavigate();
57	  const { signOut } = useAuth();
58	  const pendentesMotoboy = useSolicitacoesMotoboyCount();
59	  const tipoRestaurante = useTipoRestaurante();
60	  const navLinks = [
61	    ...LINKS.slice(0, 2), ...(tipoRestaurante ? COPA_LINK : []),
62	    ...LINKS.slice(2, 6), ...(tipoRestaurante ? SALAO_LINKS : []),
63	    ...LINKS.slice(6),
64	  ];
65	
66	  const [empresa, setEmpresa] = useState(null);
67	  const [statusAberto, setStatusAberto] = useState(false);
68	  const [caixa, setCaixa] = useState(null);
69	  const [valorInicial, setValorInicial] = useState('');
70	  const [loading, setLoading] = useState(true);
71	  const [erro, setErro] = useState(null);
72	
73	  const [showSaida, setShowSaida] = useState(false);
74	  const [salvandoSaida, setSalvandoSaida] = useState(false);
75	  const [showFechar, setShowFechar] = useState(false);
76	  const [fechando, setFechando] = useState(false);
77	  const [fechamento, setFechamento] = useState(null);
78	  const [relFretes, setRelFretes] = useState(null);
79	  const [periodoFretes, setPeriodoFretes] = useState('hoje');
80	  const [showDetalheFretes, setShowDetalheFretes] = useState(false);
81	  const [menuAberto, setMenuAberto] = useState(false);
82	  const [sidebarAberto, setSidebarAberto] = useState(false);
83	  const [nomeOperador, setNomeOperador] = useState('');
84	  const [pedidosAbertos, setPedidosAbertos] = useState([]);
85	  const [comandasAbertas, setComandasAbertas] = useState([]);
86	  const [mesasAbertas, setMesasAbertas] = useState([]);
87	  const [restauranteId, setRestauranteId] = useState(null);
88	  const [alertas, setAlertas] = useState([]);
89	  const alertaTimers = useRef({});
90	  const audioCtxRef = useRef(null);
91	  const lastCheckTimeRef = useRef(new Date().toISOString());
92	  const newPendingCountRef = useRef(0);
93	
94	  const getAudioCtx = () => {
95	    if (!audioCtxRef.current) {
96	      audioCtxRef.current = new (window.AudioContext || window.webkitAudioContext)();
97	    }
98	    return audioCtxRef.current;
99	  };
100	
101	  const playNotification = useCallback(() => {
102	    try {
103	      const ctx = getAudioCtx();
104	      const play = () => {
105	        const tone = (freq, start, dur, vol = 0.7) => {
106	          const o = ctx.createOscillator();
107	          const g = ctx.createGain();
108	          o.connect(g); g.connect(ctx.destination);
109	          o.frequency.value = freq; o.type = 'square';
110	          g.gain.setValueAtTime(vol, ctx.currentTime + start);
111	          g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + start + dur);
112	          o.start(ctx.currentTime + start);
113	          o.stop(ctx.currentTime + start + dur + 0.1);
114	        };
115	        tone(523, 0,    0.12); // C5
116	        tone(659, 0.15, 0.12); // E5
117	        tone(784, 0.3,  0.12); // G5
118	        tone(1047, 0.45, 0.3); // C6 — acorde final
119	      };
120	      if (ctx.state === 'suspended') ctx.resume().then(play);
121	      else play();
122	    } catch {}
123	  }, []);
124	
125	  // Desbloquear AudioContext no primeiro gesto do usuário
126	  useEffect(() => {
127	    const unlock = () => { try { getAudioCtx().resume(); } catch {} };
128	    window.addEventListener('click', unlock, { once: true });
129	    window.addEventListener('keydown', unlock, { once: true });
130	    return () => {
131	      window.removeEventListener('click', unlock);
132	      window.removeEventListener('keydown', unlock);
133	    };
134	  }, []);
135	
136	  // Título da aba pisca com contagem de pedidos novos quando aba não está em foco
137	  const flashTitle = useCallback((count) => {
138	    newPendingCountRef.current = count;
139	    if (document.visibilityState === 'hidden') {
140	      document.title = `(${count}) 🔔 NOVO PEDIDO!`;
141	    }
142	  }, []);
143	
144	  useEffect(() => {
145	    const onFocus = () => {
146	      newPendingCountRef.current = 0;
147	      document.title = 'Dashboard';
148	    };
149	    document.addEventListener('visibilitychange', onFocus);
150	    return () => document.removeEventListener('visibilitychange', onFocus);
151	  }, []);
152	
153	  const carregar = async () => {
154	    try {
155	      const [emp, caixaData] = await Promise.all([getMinhaEmpresa(), getCaixa()]);
156	      setEmpresa(emp.empresa);
157	      setRestauranteId(emp.empresa?.id ?? null);
158	      const deveEstarAberto = caixaData.status_restaurante === true && !!caixaData.aberto;
159	      setStatusAberto(deveEstarAberto);
160	      // Se o DB diz aberto mas caixa está fechado, sincroniza o fechamento no backend
161	      if (caixaData.status_restaurante === true && !caixaData.aberto) {
162	        toggleStatusRestaurante(false).catch(() => {});
163	      }
164	      setCaixa(caixaData);
165	    } catch (e) {
166	      setErro(e.message);
167	    } finally {
168	      setLoading(false);
169	    }
170	  };
171	
172	  const recarregarCaixa = useCallback(async () => {
173	    try {
174	      const data = await getCaixa();
175	      setCaixa(data);
176	    } catch { /* silent */ }
177	  }, []);
178	
179	  const carregarRelFretes = useCallback(async (periodo) => {
180	    try {
181	      const data = await getRelatorioFretes(periodo);
182	      setRelFretes(data);
183	    } catch { /* silent */ }
184	  }, []);
185	
186	  useEffect(() => {
187	    carregarRelFretes(periodoFretes);
188	  }, [periodoFretes, carregarRelFretes]);
189	
190	  useEffect(() => { carregar(); }, []);
191	
192	  // Auto-refresh pedidos quando caixa aberto
193	  useEffect(() => {
194	    if (!caixa?.aberto) return;
195	    const id = setInterval(recarregarCaixa, 30000);
196	    return () => clearInterval(id);
197	  }, [caixa?.aberto, recarregarCaixa]);
198	
199	  // Realtime: novo pedido → alerta visual + sonoro
200	  useEffect(() => {
201	    if (!restauranteId) return;
202	    const channel = supabase
203	      .channel(`dash-orders-${restauranteId}`)
204	      .on('postgres_changes', {
205	        event: 'INSERT',
206	        schema: 'public',
207	        table: 'orders',
208	        filter: `restaurant_id=eq.${restauranteId}`,
209	      }, (payload) => {
210	        const p = payload.new;
211	        playNotification();
212	        flashTitle(newPendingCountRef.current + 1);
213	        lastCheckTimeRef.current = p.created_at ?? new Date().toISOString();
214	        const alerta = { id: p.id, total: p.total, ts: Date.now() };
215	        setAlertas((prev) => [...prev, alerta]);
216	        alertaTimers.current[p.id] = setTimeout(() => {
217	          setAlertas((prev) => prev.filter((a) => a.id !== p.id));
218	          delete alertaTimers.current[p.id];
219	        }, 10000);
220	        recarregarCaixa();
221	      })
222	      .on('postgres_changes', {
223	        event: 'UPDATE',
224	        schema: 'public',
225	        table: 'orders',
226	        filter: `restaurant_id=eq.${restauranteId}`,
227	      }, () => recarregarCaixa())
228	      .subscribe();
229	    return () => {
230	      supabase.removeChannel(channel);
231	      Object.values(alertaTimers.current).forEach(clearTimeout);
232	    };
233	  }, [restauranteId, recarregarCaixa, playNotification, flashTitle]);
234	
235	  // Polling fallback: detecta novos pedidos caso Realtime falhe
236	  useEffect(() => {
237	    if (!restauranteId) return;
238	    const poll = async () => {
239	      try {
240	        const { data } = await supabase
241	          .from('orders')
242	          .select('id, total, created_at')
243	          .eq('restaurant_id', restauranteId)
244	          .eq('status', 'pending')
245	          .gt('created_at', lastCheckTimeRef.current)
246	          .order('created_at', { ascending: false });
247	        if (!data || data.length === 0) return;
248	        lastCheckTimeRef.current = data[0].created_at;
249	        playNotification();
250	        data.forEach((p) => {
251	          flashTitle(newPendingCountRef.current + 1);
252	          const alerta = { id: p.id, total: p.total, ts: Date.now() };
253	          setAlertas((prev) => prev.some((a) => a.id === p.id) ? prev : [...prev, alerta]);
254	          alertaTimers.current[p.id] = setTimeout(() => {
255	            setAlertas((prev) => prev.filter((a) => a.id !== p.id));
256	            delete alertaTimers.current[p.id];
257	          }, 10000);
258	        });
259	        recarregarCaixa();
260	      } catch {}
261	    };
262	    const id = setInterval(poll, 10000);
263	    return () => clearInterval(id);
264	  }, [restauranteId, playNotification, flashTitle, recarregarCaixa]);
265	
266	  const handleToggleStatus = async (novoStatus) => {
267	    if (novoStatus && !caixa?.aberto) {
268	      alert('Abra o caixa antes de abrir o restaurante para aceitar pedidos.');
269	      return;
270	    }
271	    setStatusAberto(novoStatus);
272	    try { await toggleStatusRestaurante(novoStatus); } catch (e) { setStatusAberto(!novoStatus); alert(e.message); }
273	  };
274	
275	  const handleAbrirCaixa = async () => {
276	    if (!nomeOperador.trim()) { alert('Informe o nome do operador'); return; }
277	    const vi = valorInicial !== '' ? parseFloat(valorInicial) : (caixa?.saldo_caixa ?? 0);
278	    try {
279	      const data = await abrirCaixa({ nome_operador: nomeOperador.trim(), valor_inicial: vi });
280	      setCaixa(data);
281	      setValorInicial('');
282	      setNomeOperador('');
283	    } catch (e) { alert(e.message); }
284	  };
285	
286	  const handleAdicionarSaida = async (dados) => {
287	    setSalvandoSaida(true);
288	    try {
289	      await adicionarSaida(dados);
290	      const novoCaixa = await getCaixa();
291	      setCaixa(novoCaixa);
292	      setShowSaida(false);
293	    } catch (e) { alert(e.message); } finally { setSalvandoSaida(false); }
294	  };
295	
296	  const handleFecharCaixa = async (destinacao = {}) => {
297	    setFechando(true);
298	    try {
299	      const res = await fecharCaixa(destinacao);
300	      setFechamento(res.fechamento ?? res);
301	      await recarregarCaixa();
302	      setShowFechar(false);
303	      setPedidosAbertos([]); setComandasAbertas([]); setMesasAbertas([]);
304	    } catch (e) {
305	      if (e.data?.pedidos || e.data?.comandas || e.data?.mesas) {
306	        setPedidosAbertos(e.data.pedidos ?? []);
307	        setComandasAbertas(e.data.comandas ?? []);
308	        setMesasAbertas(e.data.mesas ?? []);
309	      } else {
310	        alert(e.message);
311	      }
312	    } finally { setFechando(false); }
313	  };
314	
315	  const handleFecharETransferir = async ({ nome_operador, valor_inicial }) => {
316	    setFechando(true);
317	    try {
318	      const res = await fecharETransferir({ nome_operador, valor_inicial });
319	      setFechamento(res.fechamento);
320	      await recarregarCaixa();
321	      setShowFechar(false);
322	      setPedidosAbertos([]); setComandasAbertas([]); setMesasAbertas([]);
323	    } catch (e) { alert(e.message); } finally { setFechando(false); }
324	  };
325	
326	
327	  if (loading) return (
328	    <div className="min-h-screen flex items-center justify-center bg-[#FAFAFA]">
329	      <div className="w-8 h-8 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
330	    </div>
331	  );
332	
333	  if (erro) return (
334	    <div className="min-h-screen flex items-center justify-center bg-[#FAFAFA]">
335	      <p className="text-red-600 text-sm">{erro}</p>
336	    </div>
337	  );
338	
339	  const r = caixa?.resumo;
340	
341	  return (
342	    <div className="min-h-screen bg-[#FAFAFA]">
343	
344	      <AlertasToast alertas={alertas} onDismiss={(id) => setAlertas((prev) => prev.filter((a) => a.id !== id))} />
345	
346	      <header className="bg-white border-b border-[#E4E4E7] px-6 py-4 flex items-center justify-between">
347	        <div>
348	          <h1 className="text-xl font-bold text-[#18181B]">{empresa?.name ?? 'Meu Restaurante'}</h1>
349	          <p className="text-sm text-[#71717A]">Painel Operacional</p>
350	        </div>
351	        {/* Desktop: hamburger abre menu lateral */}
352	        <button onClick={() => setSidebarAberto(true)}
353	          className="hidden md:flex items-center gap-2 px-3 py-2 text-sm font-semibold rounded-lg text-[#27272A] hover:bg-[#F4F4F5] border border-[#E4E4E7]">
354	          <Icon name="Menu" size={18} /> Menu
355	        </button>
356	        {/* Mobile hamburger */}
357	        <button className="md:hidden p-2 rounded-lg hover:bg-[#F4F4F5] text-[#18181B]"
358	          onClick={() => setMenuAberto((v) => !v)}>
359	          <Icon name={menuAberto ? 'X' : 'Menu'} size={22} />
360	        </button>
361	      </header>
362	
363	      <RestauranteSidebar
364	        open={sidebarAberto}
365	        onClose={() => setSidebarAberto(false)}
366	        links={navLinks}
367	        activePath="/restaurante"
368	        pendentesMotoboy={pendentesMotoboy}
369	        slugLoja={empresa?.slug}
370	        onSair={async () => { await signOut(); navigate('/customer-registration-login'); }}
371	      />
372	
373	      <AnimatePresence>
374	        {menuAberto && (
375	          <MobileMenu
376	            links={navLinks}
377	            currentPath="/restaurante"
378	            pendentesMotoboy={pendentesMotoboy}
379	            slugLoja={empresa?.slug}
380	            onNavigate={(path) => { navigate(path); setMenuAberto(false); }}
381	            onSair={async () => { await signOut(); navigate('/customer-registration-login'); }}
382	          />
383	        )}
384	      </AnimatePresence>
385	
386	      <main className="p-6 w-[95%] mx-auto space-y-5">
387	
388	        {/* Fechamento anterior */}
389	        {fechamento && (
390	          <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }}
391	            className="bg-green-50 border border-green-200 rounded-xl px-5 py-3 flex items-center justify-between">
392	            <div>
393	              <p className="text-sm font-bold text-green-800">Caixa fechado com sucesso</p>
394	              <p className="text-xs text-green-600">Vendas: {fmt(fechamento.resumo?.total_vendas)} · Saldo: {fmt(fechamento.resumo?.saldo)}</p>
395	            </div>
396	            <button onClick={() => setFechamento(null)} className="text-green-400 hover:text-green-600 p-1"><Icon name="X" size={16} /></button>
397	          </motion.div>
398	        )}
399	
400	        {/* Status restaurante */}
401	        <motion.div animate={{ borderColor: statusAberto ? '#22C55E' : '#EF4444' }}
402	          className={`rounded-2xl border-2 p-4 flex items-center justify-between ${statusAberto ? 'bg-green-50' : 'bg-red-50'}`}>
403	          <div>
404	            <p className="font-black text-[#18181B]">{statusAberto ? '🟢 Restaurante ABERTO' : '🔴 Restaurante FECHADO'}</p>
405	            <p className="text-xs text-[#71717A] mt-0.5">{statusAberto ? 'Clientes podem fazer pedidos agora.' : 'Pedidos pausados.'}</p>
406	          </div>
407	          <button type="button" onClick={() => handleToggleStatus(!statusAberto)}
408	            className={`relative w-14 h-7 rounded-full transition-colors flex-shrink-0 ${statusAberto ? 'bg-green-500' : 'bg-red-400'}`}>
409	            <span className={`absolute top-1.5 w-4 h-4 bg-white rounded-full shadow transition-transform ${statusAberto ? 'left-8' : 'left-1.5'}`} />
410	          </button>
411	        </motion.div>
412	
413	        {/* Caixa — expirado (8h) */}
414	        {caixa?.expirado && (
415	          <div className="bg-red-50 border border-red-200 rounded-2xl p-4 flex items-center justify-between gap-3 flex-wrap">
416	            <div className="flex items-center gap-2">
417	              <Icon name="AlertTriangle" size={18} className="text-red-500 flex-shrink-0" />
418	              <div>
419	                <p className="text-sm font-bold text-red-800">Caixa expirado</p>
420	                <p className="text-xs text-red-600">Mais de 8h desde a abertura. Feche para continuar operando.</p>
421	              </div>
422	            </div>
423	            <button onClick={() => setShowFechar(true)}
424	              className="px-4 py-2 bg-red-500 text-white text-sm font-bold rounded-xl hover:bg-red-600 flex-shrink-0">
425	              Fechar caixa
426	            </button>
427	          </div>
428	        )}
429	
430	        {/* Caixa — fechado */}
431	        {!caixa?.aberto && !caixa?.expirado && (
432	          <div className="bg-white rounded-2xl border border-[#E4E4E7] p-5">
433	            <div className="flex items-center gap-2 mb-4">
434	              <Icon name="Wallet" size={18} className="text-[#FF441F]" />
435	              <h2 className="font-bold text-[#18181B]">Caixa</h2>
436	              <span className="ml-auto text-xs bg-[#F4F4F5] text-[#71717A] px-2 py-0.5 rounded-full font-medium">Fechado</span>
437	            </div>
438	            <div className="space-y-3">
439	              <div>
440	                <label className="block text-xs font-medium text-[#71717A] mb-1">Nome do operador *</label>
441	                <input value={nomeOperador} onChange={(e) => setNomeOperador(e.target.value)}
442	                  placeholder="Ex: João"
443	                  className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
444	              </div>
445	              <div className="flex gap-3">
446	                <div className="flex-1">
447	                  <label className="block text-xs font-medium text-[#71717A] mb-1">
448	                    Valor inicial (R$)
449	                    {(caixa?.saldo_caixa ?? 0) > 0 && <span className="ml-1 text-[#FF441F]">← cofre</span>}
450	                  </label>
451	                  <input type="number" min="0" step="0.01"
452	                    value={valorInicial !== '' ? valorInicial : (caixa?.saldo_caixa ?? '')}
453	                    onChange={(e) => setValorInicial(e.target.value)}
454	                    placeholder={caixa?.saldo_caixa > 0 ? String(caixa.saldo_caixa) : '0,00'}
455	                    className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
456	                </div>
457	                <div className="flex items-end">
458	                  <button onClick={handleAbrirCaixa}
459	                    className="px-5 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19] transition-colors whitespace-nowrap">
460	                    Abrir caixa
461	                  </button>
462	                </div>
463	              </div>
464	            </div>
465	          </div>
466	        )}
467	
