79	const RestauranteFinanceiro = () => {
80	  const navigate = useNavigate();
81	  const pendentesMotoboy = useSolicitacoesMotoboyCount();
82	  const slugLoja = useMinhaLojaSlug();
83	  const tipoRestaurante = useTipoRestaurante();
84	  const [restauranteNome, setRestauranteNome] = useState('');
85	  const [modo, setModo] = useState('dia');
86	  const [dia, setDia]   = useState(today());
87	  const [mes, setMes]   = useState(thisMonth());
88	  const [ano, setAno]   = useState(thisYear());
89	  const [ini, setIni]   = useState(today());
90	  const [fim, setFim]   = useState(today());
91	  const [dados, setDados]     = useState(null);
92	  const [label, setLabel]     = useState('');
93	  const [loading, setLoading] = useState(false);
94	  const [erro, setErro]       = useState(null);
95	  const [abaAtiva, setAbaAtiva] = useState('resumo');
96	  const [caixa, setCaixa]     = useState(null);
97	  const [historico, setHistorico] = useState([]);
98	  const [aprovando, setAprovando] = useState(null);
99	  const [taxaPagbank, setTaxaPagbank] = useState(0);
100	  const [sidebarAberto, setSidebarAberto] = useState(false);
101	
102	  const conferenciasPendentes = historico.filter(
103	    (cx) => cx.status === 'fechado' && cx.destinacao_fechamento?.conferencia_aprovada === false,
104	  );
105	
106	  const carregarDados = async () => {
107	    const [c, hist] = await Promise.all([getCaixa(), getCaixaHistorico()]);
108	    setCaixa(c);
109	    setHistorico(hist.historico ?? []);
110	  };
111	
112	  useEffect(() => {
113	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
114	    getConfig().then((cfg) => setTaxaPagbank(cfg.taxa_pagbank_percent ?? 0)).catch(() => {});
115	    carregarDados().catch(() => {});
116	    buscar();
117	  }, []); // eslint-disable-line
118	
119	  const buscar = async () => {
120	    const range = buildRange(modo, dia, mes, ano, ini, fim);
121	    if (!range) return;
122	    setLoading(true); setErro(null);
123	    try { const d = await getRelatorio(range.de, range.ate); setDados(d); setLabel(range.label); }
124	    catch (e) { setErro(e.message); }
125	    finally { setLoading(false); }
126	  };
127	
128	  const handleAprovarConferencia = async (caixaId) => {
129	    setAprovando(caixaId);
130	    try { await aprovarConferencia(caixaId); await carregarDados(); }
131	    catch (e) { alert(e.message ?? 'Erro ao aprovar'); }
132	    finally { setAprovando(null); }
133	  };
134	
135	  const r = dados?.resumo;
136	  const cashTotal    = r?.por_pagamento?.cash?.total ?? 0;
137	  const digitalTotal = Object.entries(r?.por_pagamento ?? {}).filter(([k]) => k !== 'cash').reduce((s, [, v]) => s + v.total, 0);
