368	      .then((lista) => setImpressorasCozinha((lista ?? []).filter((i) => (i.setor ?? '').toLowerCase().includes('cozinha'))))
369	      .catch(() => setImpressorasCozinha([]));
370	
371	    if (modoToken) {
