384	        setRestauranteId(d.empresa?.id ?? null);
385	      })
386	      .catch(() => {});
387	
388	    carregar(nome);
389	    const id = setInterval(() => carregar(nome), 30000);
390	    return () => clearInterval(id);
391	  }, [carregar, modoToken, authed]);
392	
393	  useEffect(() => {
394	    if (!impressorasCozinha) return;
