380	  async adicionarItens(id: number, restaurantId: number, itens: ItemComandaBody[]) {
381	    if (!itens?.length) throw new BadRequestException('Informe ao menos 1 item');
382	
383	    const comanda = await this.buscarComanda(id, restaurantId);
384	    if (comanda.status !== 'aberta') throw new BadRequestException('Comanda não está aberta');
385	
386	    const prodIds = itens.map((i) => i.product_id);
387	    const { data: produtos, error: errProd } = await this.supabase.client
388	      .from('products')
389	      .select('id, price, is_active')
390	      .in('id', prodIds);
391	    if (errProd) throw errProd;
392	
393	    const prodMap = Object.fromEntries((produtos ?? []).map((p) => [p.id, p]));
394	    for (const item of itens) {
395	      const prod = prodMap[item.product_id];
396	      if (!prod) throw new BadRequestException(`Produto ${item.product_id} não encontrado`);
397	      if (!prod.is_active) throw new BadRequestException(`Produto ${item.product_id} inativo`);
398	    }
399	
400	    const { error } = await this.supabase.client.from('order_items').insert(
401	      itens.map((i) => ({
402	        order_id: id,
403	        product_id: i.product_id,
404	        quantity: i.quantity,
405	        unit_price: prodMap[i.product_id].price,
406	        observacao: i.observacao?.trim() || null,
407	        status: 'pendente',
408	      })),
409	    );
410	    if (error) throw error;
411	
412	    const { data: todosItens } = await this.supabase.client.from('order_items').select('quantity, unit_price').eq('order_id', id);
413	    const total = (todosItens ?? []).reduce((acc: number, i: any) => acc + i.quantity * i.unit_price, 0);
414	    await this.supabase.client.from('orders').update({ total: parseFloat(total.toFixed(2)) }).eq('id', id);
415	
416	    await this.salaoService.enviarItensComoRestaurante(id, comanda);
417	    return this.comandaDetalhe(id, restaurantId);
418	  }
419	
420	  // Estabelecimento pode remover qualquer item (pendente ou já enviado) — diferente do
421	  // garçom, que só mexe em item ainda não enviado (ver salao.service.ts).
422	  // Estabelecimento pode editar qualquer item (pendente ou já enviado) — diferente do
423	  // garçom, que só mexe em item ainda não enviado (ver salao.service.ts).
424	  async editarItem(comandaId: number, restaurantId: number, itemId: number, body: { quantity?: number; observacao?: string }) {
425	    const comanda = await this.buscarComanda(comandaId, restaurantId);
426	    if (!['aberta', 'fechada_garcom'].includes(comanda.status)) {
427	      throw new BadRequestException('Comanda já foi paga ou cancelada');
428	    }
429	
430	    const { data: item } = await this.supabase.client
431	      .from('order_items').select('id').eq('id', itemId).eq('order_id', comandaId).maybeSingle();
432	    if (!item) throw new NotFoundException('Item não encontrado');
433	
434	    const update: Record<string, unknown> = {};
435	    if (body.quantity !== undefined) {
436	      if (body.quantity < 1) throw new BadRequestException('Quantidade mínima é 1');
437	      update.quantity = body.quantity;
438	    }
439	    if (body.observacao !== undefined) update.observacao = body.observacao?.trim() || null;
440	
441	    const { error } = await this.supabase.client.from('order_items').update(update).eq('id', itemId);
442	    if (error) throw error;
443	
